// cost: n x n row-major double. perm: output, perm[i] = assigned object.
void auction(int n, const double* cost, int* perm, double eps_final) {
    double* price = (double*)calloc(n, sizeof(double));
    int* p2o = (int*)malloc(n * sizeof(int));  // person -> object
    int* o2p = (int*)malloc(n * sizeof(int));  // object -> person
    for (int i = 0; i < n; i++) { p2o[i] = -1; o2p[i] = -1; }

    double maxc = 0.0;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (cost[i*n+j] > maxc) maxc = cost[i*n+j];

    double eps = (maxc > 0 ? maxc : 1.0) / 4.0;

    while (eps > eps_final) {
        for (int i = 0; i < n; i++) p2o[i] = -1;
        for (int j = 0; j < n; j++) o2p[j] = -1;

        // find first unassigned
        int i = 0;
        while (1) {
            // find an unassigned person
            while (i < n && p2o[i] != -1) i++;
            if (i >= n) break;

            const double* row = cost + (size_t)i * n;
            double best_val = -1e300, second_val = -1e300;
            int best_j = -1;
            for (int j = 0; j < n; j++) {
                double v = -row[j] - price[j];
                if (v > best_val) {
                    second_val = best_val;
                    best_val = v;
                    best_j = j;
                } else if (v > second_val) {
                    second_val = v;
                }
            }
            double bid = (best_val - second_val) + eps;
            price[best_j] += bid;
            int prev = o2p[best_j];
            p2o[i] = best_j;
            o2p[best_j] = i;
            if (prev != -1) {
                p2o[prev] = -1;
                i = prev;  // continue with the displaced person
            } else {
                i++;  // move to next person
            }
        }
        eps = eps / 2.0;
    }

    for (int i = 0; i < n; i++) perm[i] = p2o[i];
    free(price); free(p2o); free(o2p);
}
