        for (int j = 0; j < n; j++)
            if (cost[i*n+j] > maxc) maxc = cost[i*n+j];

    double eps = (maxc > 0 ? maxc : 1.0) / 4.0;

    while (eps > eps_final) {
        // reset assignments (keep prices)
        for (int i = 0; i < n; i++) p2o[i] = -1;
        for (int j = 0; j < n; j++) o2p[j] = -1;

        int done = 0;
        while (!done) {
            done = 1;
            // forward auction: all unassigned persons
            for (int i = 0; i < n; i++) {
                if (p2o[i] != -1) continue;
                done = 0;
                const double* row = cost + (size_t)i * n;
                double best = -1e300, second = -1e300;
                int best_j = -1;
                for (int j = 0; j < n; j++) {
                    double v = -row[j] - p[j];
                    if (v > best) { second = best; best = v; best_j = j; }
                    else if (v > second) second = v;
                }
                double bid = (best - second) + eps;
                p[best_j] += bid;
                pi[i] = best;
                int prev = o2p[best_j];
                p2o[i] = best_j;
                o2p[best_j] = i;
                if (prev != -1) p2o[prev] = -1;
            }
            // reverse auction: all unassigned objects
            for (int j = 0; j < n; j++) {
                if (o2p[j] != -1) continue;
                done = 0;
                double best = -1e300, second = -1e300;
                int best_i = -1;
                for (int i = 0; i < n; i++) {
                    double v = -cost[i*n+j] - pi[i];
                    if (v > best) { second = best; best = v; best_i = i; }
                    else if (v > second) second = v;
                }
                double bid = (best - second) + eps;
                pi[best_i] += bid;
                p[j] = best;
                int prev = p2o[best_i];
                o2p[j] = best_i;
                p2o[best_i] = j;
                if (prev != -1) o2p[prev] = -1;
            }
        }
        eps = eps / 2.0;
    }

